using System;using System.Collections.Generic;using System.IO;using System.Text;using System.Security.AccessControl;using System.Security.Principal;using Enclave.OwnedRpc;
public static class NativeRpcControllerHarness {
 static int count;static void Check(bool x){if(!x)throw new Exception("Assertion");}static void Refuse(Action f){bool hit=false;try{f();}catch{hit=true;}Check(hit);}static void Test(string n,Action f){f();count++;Console.WriteLine("PASS "+n);}
 static Dictionary<string,object> D(params object[] a){var d=new Dictionary<string,object>();for(int i=0;i<a.Length;i+=2)d.Add((string)a[i],a[i+1]);return d;}
 static string H(char c){return new string(c,64);}static void Put(string path,byte[] bytes){var a=new FileSecurity();a.SetOwner(new SecurityIdentifier("S-1-5-32-544"));a.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})a.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,AccessControlType.Allow));using(var f=new FileStream(path,FileMode.CreateNew,FileSystemRights.WriteData,FileShare.None,4096,FileOptions.WriteThrough,a)){f.Write(bytes,0,bytes.Length);f.Flush(true);}}
 sealed class Case {
  internal readonly string Root,Hash=H('a'),Epoch=new string('b',32),Instance="rpc"+new string('c',32),Deployment="0x"+H('d');internal readonly long Origin=BoundedWorker.MonotonicMilliseconds();
  internal Case(){Root=Path.Combine(Path.GetPathRoot(Environment.SystemDirectory),"rpc-controller-fixture-"+Guid.NewGuid().ToString("N"));var a=new DirectorySecurity();a.SetOwner(new SecurityIdentifier("S-1-5-32-544"));a.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})a.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.CreateDirectory(Root,a);Put(Path.Combine(Root,"manager.lock"),new byte[0]);}
  internal void Current(){if(BoundedWorker.MonotonicMilliseconds()>=Origin+20000)throw new Exception("Fixture original deadline");}
  internal NativeRpcManagerLedger Open(){return new NativeRpcManagerLedger(Root,Hash,Current);}
  internal Dictionary<string,object> Begin(NativeRpcManagerLedger l){return l.Begin(Epoch,Instance,Deployment,Origin);}
  internal string Digest(Dictionary<string,object> a){return ProtectedAttempt.Hash(NativeRpcManagerLedger.Encode(a));}
  internal Dictionary<string,object> Launch(Dictionary<string,object> a){return D("managerEpoch",Epoch,"id",Instance,"instanceId",Instance,"name",Deployment,"originalClock",D("originMs",a["originMs"],"deadlineMs",a["deadlineMs"]),"physicalMemoryMiB",20480,"memory",D("appMiB",19456),"cpu",D("vcpus",4,"grantedUnits",400000,"appCpuPercent",400));}
 }
 public static int Main(){try{
  BoundedWorker.EnterSupervisorEnvelope(256UL*1024*1024);
  Test("native begin durably records original QPC and whole reservation",()=>{var c=new Case();using(var l=c.Open()){var a=c.Begin(l);Check((string)a["originMs"]==c.Origin.ToString());Check(Int64.Parse((string)a["deadlineMs"])==c.Origin+900000);Check((int)a["physicalMemoryMiB"]==20480);Check(!(bool)a["reservationMayRelease"]);Check(File.Exists(Path.Combine(c.Root,"attempt.json")));Check((string)l.Original(c.Digest(a))["instance"]==c.Instance);}});
  Test("restart cannot begin again even under a different manager identity",()=>{var c=new Case();Dictionary<string,object> a;using(var l=c.Open())a=c.Begin(l);using(var l=c.Open()){Refuse(()=>l.RequireEmpty());Refuse(()=>l.Begin(new string('e',32),"rpc"+new string('f',32),"0x"+H('e'),c.Origin));Check((string)l.Original(c.Digest(a))["managerEpoch"]==c.Epoch);}});
  Test("empty torn intent and extra inventory remain consumed",()=>{var c=new Case();Put(Path.Combine(c.Root,"attempt.json.pending"),new byte[0]);using(var l=c.Open()){Refuse(()=>c.Begin(l));Refuse(()=>l.Original(H('e')));}c=new Case();Put(Path.Combine(c.Root,"foreign.txt"),new byte[]{1});using(var l=c.Open())Refuse(()=>c.Begin(l));});
  Test("exact ledger lock excludes competing writers",()=>{var c=new Case();using(var l=c.Open())Refuse(()=>{using(var other=c.Open())other.RequireEmpty();});using(var l=c.Open())c.Begin(l);});
  Test("lost launch reply remains one shot across restart",()=>{var c=new Case();Dictionary<string,object> a;Dictionary<string,object> launch;using(var l=c.Open()){a=c.Begin(l);launch=c.Launch(a);l.ConsumeLaunch(c.Digest(a),launch);}using(var l=c.Open()){Refuse(()=>l.ConsumeLaunch(c.Digest(a),launch));Check(File.Exists(Path.Combine(c.Root,"launch.json")));Check(!File.Exists(Path.Combine(c.Root,"dispatch.json")));}});
  Test("changed epoch clock and reservation refuse before launch intent",()=>{foreach(string field in new[]{"managerEpoch","clock","memory"}){var c=new Case();using(var l=c.Open()){var a=c.Begin(l);var launch=c.Launch(a);if(field=="managerEpoch")launch[field]=new string('f',32);else if(field=="clock")((Dictionary<string,object>)launch["originalClock"])["deadlineMs"]=(c.Origin+900001).ToString();else launch["physicalMemoryMiB"]=20479;Refuse(()=>l.ConsumeLaunch(c.Digest(a),launch));Check(!File.Exists(Path.Combine(c.Root,"launch.json")));}}});
  Test("changed config or attempt digest cannot rehydrate original",()=>{var c=new Case();Dictionary<string,object> a;using(var l=c.Open())a=c.Begin(l);using(var l=new NativeRpcManagerLedger(c.Root,H('f'),c.Current))Refuse(()=>l.Original(c.Digest(a)));using(var l=c.Open())Refuse(()=>l.Original(H('f')));});
  Test("actual held immutable input blocks modification and replacement",()=>{var c=new Case();string path=Path.Combine(c.Root,"source.bin");byte[] bytes=Encoding.UTF8.GetBytes("public controller input fixture");Put(path,bytes);using(var f=new NativeControllerFiles(c.Current)){Check(ProtectedAttempt.Hash(f.Read(path,1024,ProtectedAttempt.Hash(bytes)))==ProtectedAttempt.Hash(bytes));Refuse(()=>{using(var o=File.OpenWrite(path))o.WriteByte(2);});Refuse(()=>File.Move(path,path+".old"));Refuse(()=>f.Read(path,1024,H('f')));}});
  Test("exact native plan derives from original attempt and shared claim",()=>{var c=new Case();using(var l=c.Open()){var a=c.Begin(l);var launch=c.Launch(a);launch["appId"]=H('e');launch["recordSha256"]=H('f');launch["record"]=D("runtimeId",H('b'),"rpc",D("profileSha256",H('c')),"secretDeployment",c.Deployment,"derivation","enclave-catalog-bundle/9");string id=ProtectedAttempt.Hash(NativeRpcManagerLedger.Encode(new[]{c.Epoch,c.Instance,H('e')}));launch["physicalClaim"]=D("poolHash",H('a'),"boot",a["boot"],"actor","app-native","id",id,"bytes",21474836480L);var cfg=D("runtimeId",H('b'),"profileSha256",H('c'),"admissionSha256",H('d'),"attemptsRoot",c.Root,"firmwareSha256",H('e'),"initialStateSha256",H('f'),"workerSha256",H('a'));var plan=NativeRpcControllerEntry.MakePlan(a,cfg,launch);Check(plan.Origin==c.Origin&&plan.Deadline==c.Origin+900000&&plan.Claim==id);Check(plan.Attempt==(string)a["attempt"]&&plan.Root==Path.Combine(c.Root,plan.Attempt));string guid="12345678-1234-1234-1234-123456789012";string system=StartRecords.Encode(D("receipt",H('a'),"system","Msvm_ComputerSystem.Name=\""+guid+"\""));string owned=StartRecords.Encode(D("schema","native-rpc-owned-off/1","plan",plan.Digest,"system",ProtectedAttempt.Hash(Encoding.UTF8.GetBytes(system)),"vmGuid",guid,"app",plan.App,"deployment",plan.Deployment,"instance",plan.Instance,"managerEpoch",plan.ManagerEpoch,"startAuthorized",false,"reservationMayRelease",false));var result=D("ownedReceipt",ProtectedAttempt.Hash(Encoding.UTF8.GetBytes(owned)),"vmGuid",guid);NativeRpcControllerEntry.VerifyOwnedResult(plan,result,system,owned);result["ownedReceipt"]=owned;Refuse(()=>NativeRpcControllerEntry.VerifyOwnedResult(plan,result,system,owned));((Dictionary<string,object>)launch["physicalClaim"])["id"]=H('f');Refuse(()=>NativeRpcControllerEntry.MakePlan(a,cfg,launch));}});
  Test("private copy hash failure preserves pending and blocks replay",()=>{var c=new Case();string target=Path.Combine(c.Root,"asset.bin");using(var files=new NativeControllerFiles(c.Current)){Refuse(()=>{using(var b=new MemoryStream(new byte[]{1}))files.Copy(target,b,2,H('f'));});Check(File.Exists(target+".pending"));Refuse(()=>files.Publish(target,new byte[]{1}));Check(!File.Exists(target));}});
  Console.WriteLine("TOTAL "+count+" PASS; actual administrator ledger/files; task producer compiled only; no SYSTEM tasks or WMI");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
